// Generic class
public class Repository<T> where T : class {
    private readonly List<T> _items = new();

    public void Add(T item) {
        _items.Add(item);
    }

    public T GetById(int id) {
        return _items.FirstOrDefault();
    }
}

// Usage
var userRepo = new Repository<User>();
var productRepo = new Repository<Product>();

userRepo.Add(new User { Name = "John" });
productRepo.Add(new Product { Name = "Laptop" });

// Generic method
public T Max<T>(T a, T b) where T : IComparable<T> {
    return a.CompareTo(b) > 0 ? a : b;
}

// Generic constraints
public class Service<T> 
    where T : class, new() {
    // T must be a class with parameterless constructor
}

// Before generics (boxing!)
ArrayList list = new ArrayList();
list.Add(1); // boxing
list.Add(2); // boxing

// With generics (no boxing!)
List<int> genericList = new List<int>();
genericList.Add(1); // no boxing
genericList.Add(2); // no boxing
